import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join, resolve, sep } from 'node:path';

export const FILE_STORAGE = Symbol('FILE_STORAGE');

/** Where file bytes live. Keys are generated by the API (never from user input). */
export interface FileStorage {
  put(key: string, data: Uint8Array): Promise<void>;
  get(key: string): Promise<Buffer>;
}

const KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/;

/** Files on a local disk or mounted volume: one file per key, written atomically, readable only by us. */
export class LocalFileStorage implements FileStorage {
  private readonly root: string;

  constructor(dir: string) {
    this.root = resolve(dir);
  }

  private path(key: string): string {
    if (!KEY.test(key)) throw new Error('Invalid storage key');
    const full = resolve(this.root, key);
    if (!full.startsWith(this.root + sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, data: Uint8Array): Promise<void> {
    const full = this.path(key);
    await mkdir(dirname(full), { recursive: true, mode: 0o700 });
    const temp = join(dirname(full), `.${randomUUID()}.partial`);
    await writeFile(temp, data, { mode: 0o600, flag: 'wx' });
    await rename(temp, full);
  }

  async get(key: string): Promise<Buffer> {
    return readFile(this.path(key));
  }
}
